mapper.select:
SELECT o.id, o.transfer_no, o.warehouse_id, w.warehouse_name, o.erp_tenant_id, t.tenant_name AS owner_name, COALESCE(o.wms_tenant_id, t.parent_wms_tenant_id) AS wms_tenant_id, op.tenant_name AS operator_name, o.order_status, o.source_type, o.source_id, o.source_no, o.reason_code, o.reason, o.remark, o.complete_time, o.create_by, COALESCE(NULLIF(create_user.nickname, ''), create_user.username) AS create_by_name, o.complete_by, COALESCE( NULLIF(complete_user.nickname, ''), complete_user.username, NULLIF(create_user.nickname, ''), create_user.username ) AS operator_user_name, o.create_time FROM wms_location_transfer_order o LEFT JOIN wms_warehouse w ON o.warehouse_id = w.id LEFT JOIN sys_tenant t ON t.id = o.erp_tenant_id LEFT JOIN sys_tenant op ON op.id = COALESCE(o.wms_tenant_id, t.parent_wms_tenant_id) LEFT JOIN sys_user create_user ON create_user.user_id = o.create_by AND create_user.deleted = 0 LEFT JOIN sys_user complete_user ON complete_user.user_id = o.complete_by AND complete_user.deleted = 0
AND o.deleted = 0
AND o.transfer_no LIKE CONCAT('%', #{qo.transferNo}, '%')
AND o.warehouse_id = #{qo.warehouseId}
AND o.erp_tenant_id = #{qo.erpTenantId}
AND t.parent_wms_tenant_id = #{qo.wmsTenantId}
AND COALESCE(o.complete_by, o.create_by) = #{qo.operatorUserId}
AND o.order_status = #{qo.orderStatus}
AND o.source_type = #{qo.sourceType}
AND DATE(o.create_time) >= #{qo.createTimeStart}
AND DATE(o.create_time) <= #{qo.createTimeEnd}
ORDER BY o.create_time DESC

SELECT transfer_order_id AS transferOrderId, COUNT(*) AS itemCount, COALESCE(SUM(quantity), 0) AS totalQuantity FROM wms_location_transfer_item WHERE transfer_order_id IN
#{id}
GROUP BY transfer_order_id
